const c={enabled:!1,mode:"invert",brightness:90,temperature:50};chrome.commands.onCommand.addListener(async n=>{if(n==="toggle-nightmode")try{const[e]=await chrome.tabs.query({active:!0,currentWindow:!0});if(!(e!=null&&e.id)||!e.url)return;let t;try{t=new URL(e.url).hostname}catch{return}if(!t)return;const r=(await chrome.storage.local.get("sites")).sites||{},a={...c,...r[t]||{}};a.enabled=!a.enabled,r[t]=a,await chrome.storage.local.set({sites:r});try{await chrome.tabs.sendMessage(e.id,{type:"nm:update",state:a})}catch{}}catch{}});
